import java.util.Scanner;
public class DisplayTime1 {
	public static void main(String[] args) {
		//Khatwa 1: Qira althawani
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil adad lilthawani: ");
		int seconds = scan.nextInt();
		scan.close();
		//Khatwa 2: Istikhraj aldaqaeq walthawani almutabqia min althawani almadkhalah
		int minutes = seconds / 60; 
		int remainingSeconds = seconds % 60;
		//Khatwa 3: Ard alnataija
		System.out.println(seconds + " thawani hiya " + minutes +    " daqaeq wa " + remainingSeconds + " thawani.");  
	}
}
